1: % Analytic schematic, manually derived from transport_theory.tex:
2: % asm:abstract-transport, eq:transported-score-new, prop:reference-width-floor.
3: % Native body-size TikZ; requires only the existing TikZ/PGF dependency.
4: % Arrows denote conditional certificate comparisons, not causal effects.
5: \begin{tikzpicture}[x=1cm,y=1cm,
6:   every node/.style={font=\normalsize,inner sep=0pt},
7:   cert/.style={draw=blue!55!black,line width=.65pt,->},
8:   object/.style={draw=black!28,fill=black!2,rounded corners=2pt,
9:     minimum width=3.6cm,minimum height=1.25cm,align=center}]
10:   \path[use as bounding box] (0,-6.8) rectangle (16.2,.3);
11:   \node[anchor=west] at (0,0)
12:     {\textbf{Before the reward: conditional certificate comparisons}};
13: 
14:   \node[object] (reference) at (1.8,-1.15)
15:     {Frozen confidence\\[5pt]$\bVbar_t,\ \bar s_t(a)$};
16:   \node[object] (current) at (6,-1.15)
17:     {Exact current metric\\[5pt]$\bV_t,\ s_t(a)$};
18:   \node[object] (operator) at (10.2,-1.15)
19:     {Applied SPD operator\\[5pt]$\Calg_t,\ s_{\Calg,t}(a)$};
20:   \node[object] (width) at (14.4,-1.15)
21:     {Numerical score width\\[5pt]$\hat s_t(a)$};
22:   \draw[cert] (reference.east) -- node[above=5pt]{A} (current.west);
23:   \draw[cert] (current.east) -- node[above=5pt]{B} (operator.west);
24:   \draw[cert] (operator.east) -- node[above=5pt]{C} (width.west);
25: 
26:   \node[anchor=north west,align=left] at (0,-2.2)
27:     {\textbf{A\quad Metric transport}\\[8pt]
28:      $e^{-\bar D_t}\bVbar_t\preceq\bV_t
29:        \preceq e^{\bar D_t}\bVbar_t$\\[7pt]
30:      Certified path-length envelope $\bar D_t$.};
31:   \node[anchor=north west,align=left] at (5.5,-2.2)
32:     {\textbf{B\quad Operator comparison}\\[8pt]
33:      $\kappa_{-,t}\bV_t\preceq\Calg_t
34:        \preceq\kappa_{+,t}\bV_t$\\[7pt]
35:      Two-sided SPD comparison.};
36:   \node[anchor=north west,align=left] at (11,-2.2)
37:     {\textbf{C\quad Solver certificate}\\[8pt]
38:      $s_{\Calg,t}(a)\le\hat s_t(a)$\quad every $a$\\[7pt]
39:      $\hat s_t(a_t)\le\alpha_t s_{\Calg,t}(a_t)$\\[7pt]
40:      Sharpness: played action only.};
41: 
42:   \draw[black!28,line width=.5pt] (0,-4.6) -- (16.2,-4.6);
43:   \node[anchor=west] at (0,-4.95)
44:     {Selection and sharpness use the \textbf{same realized width map} $\hat s_t(\cdot)$.};
45:   \node[anchor=west] at (0,-5.57)
46:     {\textbf{Direct reference comparison}\quad Same history, center, radius, and bias.};
47:   \node[anchor=west] at (0,-6.11)
48:     {$w_t^{\rm tr}(a)=e^{\bar D_t/2}\sqrt{\kappa_{+,t}}\,\hat s_t(a)
49:        \ge\bar s_t(a)$;\quad exact actionwise correction gives $c_t(a)s_t(a)=\bar s_t(a)$.};
50:   \node[anchor=west] at (0,-6.65)
51:     {These comparisons do not order the regret of policies with different adaptive histories.};
52: \end{tikzpicture}
